{
  "justification": "The electorate prioritizes public services (especially the NHS) and leans toward higher public spending, while also exhibiting very strong punitive/authority attitudes on crime; overall left-right placement is near the midpoint. EU integration is only modestly salient and opinion is mixed, and there is little direct evidence of purity concerns—so weights emphasize authority and care, with secondary equality/proportionality and lower loyalty/sanctity.",
  "foundations": [
    {"foundation": "authority", "basis": "77.9% agree violent criminals should lose some human rights; law and order salience 6.4%.", "weight": 0.28},
    {"foundation": "care", "basis": "NHS is top issue (24.3%) and economic item leans to raise taxes/spend more (mean 6.43/10).", "weight": 0.23},
    {"foundation": "equality", "basis": "Preference for higher public spending (6.43/10) on universal services (NHS, education 36.1% combined salience).", "weight": 0.18},
    {"foundation": "proportionality", "basis": "Strong punitive stance on violent criminals implies desert/reciprocity; left-right mean near midpoint (5.03/10).", "weight": 0.16},
    {"foundation": "loyalty", "basis": "EU integration views are split (42.6% approve vs 33.2% disapprove) and EU issues low salience (7.4% total).", "weight": 0.10},
    {"foundation": "sanctity", "basis": "Purity-related issues scarcely salient (environment 1.9%, no moral-purity items among top concerns).", "weight": 0.05}
  ]
}
